-- Pontos de atenção e anormalidades técnicas em aberto (eventos "observation" com prefixo) persistem entre os meses:
-- não entram no arquivamento mensal, portanto nunca são apagados pela purga enquanto não forem resolvidos.
CREATE OR REPLACE FUNCTION public.prepare_archive_month(_month date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores'; END IF; RETURN jsonb_build_object('version',1,'month',date_trunc('month',_month)::date,'exported_at',now(),'events',coalesce((SELECT jsonb_agg(to_jsonb(e)) FROM public.client_events e WHERE event_date>=date_trunc('month',_month)::date AND event_date<(date_trunc('month',_month)+interval '1 month')::date AND NOT (e.kind='observation' AND (e.description LIKE '[Ponto de atenção]%' OR e.description LIKE '[Anormalidade técnica]%') AND coalesce(e.status,'') !~* '(resolvid|conclu|encerrad)')),'[]'::jsonb),'bypasses',coalesce((SELECT jsonb_agg(to_jsonb(b)) FROM public.bypasses b WHERE end_date>=date_trunc('month',_month)::date AND end_date<(date_trunc('month',_month)+interval '1 month')::date),'[]'::jsonb),'clients',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM public.clients c),'[]'::jsonb),'sensors',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.client_sensors s),'[]'::jsonb),'devices',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM public.client_devices d),'[]'::jsonb),'users',coalesce((SELECT jsonb_agg(to_jsonb(u)) FROM public.client_users u),'[]'::jsonb),'fields',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM public.custom_fields f),'[]'::jsonb),'operators',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name)) FROM public.profiles p),'[]'::jsonb)); END $$;
